@Document(indexName = "products")
public class ProductDocument {
    @Id
    private String id;

    @Field(type = FieldType.Text, analyzer = "standard")
    private String name;

    @Field(type = FieldType.Double)
    private Double price;

    // Getters, setters, and constructors omitted for brevity
}

@Repository
public interface ProductRepository extends ElasticsearchRepository<ProductDocument, String> {
    List<ProductDocument> findByNameContaining(String name);
}

@Service
public class ProductSearchService {
    private final ProductRepository productRepository;

    public ProductSearchService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    public List<ProductDocument> searchProducts(String query) {
        try {
            return productRepository.findByNameContaining(query);
        } catch (DataAccessResourceFailureException e) {
            // Handle NIO socket/connection failures or cluster unavailability
            throw new SearchClusterUnavailableException("Elasticsearch node unreachable", e);
        } catch (OptimisticLockingFailureException e) {
            // Handle concurrent document version conflicts during updates
            throw new ConcurrentUpdateException("Document was modified concurrently", e);
        }
    }
}
